// ── CONFIGURE THESE TWO VALUES ───────────────────────────────
const ORG_SLUG       = 'YOUR_ORG_SLUG';        // e.g. 'AcmeCorp'
const WORKSPACE_SLUG = 'YOUR_WORKSPACE_SLUG';  // e.g. 'product-team'
// ─────────────────────────────────────────────────────────────

const webhook = $('VNTANA — Asset Published').first().json.body;
const product = $('Get Product Details').first().json;

const uuid = webhook.product.uuid;
const name = product.name || webhook.product.name || 'Unnamed Asset';

// Build tag list (Title Case, comma-separated)
const tags = (product.tags || [])
  .map(t => t.name)
  .filter(Boolean)
  .join(', ') || '_No tags yet_';

// Polygon count — location varies by asset type; adjust path if needed
const polygons = (
  product.modelOpsParameters?.polygonCount ||
  product.metadata?.polygonCount ||
  product.asset?.polygonCount ||
  null
);
const polygonText = polygons
  ? Number(polygons).toLocaleString()
  : '_Not available_';

const vntanaUrl = `https://platform.vntana.com/${ORG_SLUG}/${WORKSPACE_SLUG}/products/details/${uuid}`;

return [{
  json: {
    assetName: name,
    tags: tags,
    polygons: polygonText,
    vntanaUrl: vntanaUrl,
    uuid: uuid
  },
  binary: $input.first().binary  // pass render binary through
}];
